// PARM value conversion by registry field unit: 0 none,
// 1 = ns -> cycles (x GHz), 2 = per-ns rate -> per cycle
// (/ GHz).  Reference clock = LNCH.reference_sm_clock_khz.
inline constexpr std::uint32_t field_unit_conversion(
    std::uint32_t schema, std::uint32_t field) {
  switch (schema) {
    case 21:
      switch (field) {
        case 0: case 1: case 3: case 4: case 6: case 8: case 9: return 2;
        default: return 0;
      }
    case 23:
      switch (field) {
        case 1: case 2: case 3: case 4: return 1;
        case 0: return 2;
        default: return 0;
      }
    case 24:
      switch (field) {
        case 0: case 1: case 3: case 4: case 6: return 1;
        default: return 0;
      }
    default: return 0;
  }
}

